    int start = (t1 % 12) * 3600;
    int finish = (t2 % 12) * 3600;

    vector<int> hands = {hourHand, minuteHand, secondHand};

    if (start == finish) {
        for (int hand : hands) {
            if (hand == start) {
                cout << "NO";
                return 0;
            }
        }
        cout << "YES";
        return 0;
    }

    auto onClockwiseArc = [&](int point, int from, int to) {
        if (from < to)
            return from < point && point < to;
        return point > from || point < to;
    };

    bool clockwiseClear = true;
    bool counterclockwiseClear = true;

    for (int hand : hands) {
        if (hand == start || hand == finish) {
            cout << "NO";
            return 0;
        }

        if (onClockwiseArc(hand, start, finish))
            clockwiseClear = false;
        if (onClockwiseArc(hand, finish, start))
            counterclockwiseClear = false;
    }

    cout << (clockwiseClear || counterclockwiseClear ? "YES" : "NO");
    return 0;
}

